// NEMA 23 motor mount plate.
$fn = 72;
size = 65.14;
thickness = 8;
spacing = 47.14;
bolt_d = 5.2;
pilot_d = 38.5;
radius = 4;

difference() {
    hull()
        for (x = [radius, size - radius], y = [radius, size - radius])
            translate([x, y, 0]) cylinder(h = thickness, r = radius);
    translate([size / 2, size / 2, -1])
        cylinder(h = thickness + 2, d = pilot_d);
    for (dx = [-spacing / 2, spacing / 2], dy = [-spacing / 2, spacing / 2])
        translate([size / 2 + dx, size / 2 + dy, -1])
            cylinder(h = thickness + 2, d = bolt_d);
}

// Enclosure lid with a closed gasket groove.
$fn = 64;
width = 75;
depth = 55;
thickness = 4;
groove_w = 2.5;
groove_d = 2.5;
margin = 8;
hole_d = 3.2;

difference() {
    cube([width, depth, thickness]);
    difference() {
        translate([margin, margin, thickness - groove_d])
            cube([width - 2 * margin, depth - 2 * margin, groove_d + 1]);
        translate([margin + groove_w, margin + groove_w, thickness - groove_d - 1])
            cube([
                width - 2 * (margin + groove_w),
                depth - 2 * (margin + groove_w),
                groove_d + 3
            ]);
    }
    for (x = [margin / 2 + 1, width - margin / 2 - 1],
         y = [margin / 2 + 1, depth - margin / 2 - 1])
        translate([x, y, -1]) cylinder(h = thickness + 2, d = hole_d);
}

// Split shaft coupler 6 mm to 6.35 mm.
$fn = 72;
bore_a = 6;
bore_b = 6.35;
length = 36;
outer_d = 19.35;
slot_w = 1.6;

difference() {
    cylinder(h = length, d = outer_d);
    translate([0, 0, -1]) cylinder(h = length / 2 + 1, d = bore_a);
    translate([0, 0, length / 2]) cylinder(h = length / 2 + 1, d = bore_b);
    translate([-outer_d / 2 - 1, -slot_w / 2, length * 0.08])
        cube([outer_d + 2, slot_w, length * 0.34]);
    translate([-outer_d / 2 - 1, -slot_w / 2, length * 0.58])
        cube([outer_d + 2, slot_w, length * 0.34]);
    for (z = [length * 0.25, length * 0.75])
        translate([0, outer_d / 2 + 1, z]) rotate([90, 0, 0])
            cylinder(h = outer_d + 2, d = 3.2);
}

// Conical pipe reducer 52 mm to 28 mm.
$fn = 96;
large_d = 52;
small_d = 28;
wall = 4;
cone_l = 24;
collar_a = 10;
collar_b = 14;

difference() {
    union() {
        cylinder(h = collar_a, d = large_d);
        translate([0, 0, collar_a])
            cylinder(h = cone_l, d1 = large_d, d2 = small_d);
        translate([0, 0, collar_a + cone_l])
            cylinder(h = collar_b, d = small_d);
    }
    translate([0, 0, -1])
        cylinder(h = collar_a + 1, d = large_d - 2 * wall);
    translate([0, 0, collar_a])
        cylinder(h = cone_l, d1 = large_d - 2 * wall, d2 = small_d - 2 * wall);
    translate([0, 0, collar_a + cone_l])
        cylinder(h = collar_b + 1, d = small_d - 2 * wall);
}

// Slotted L-bracket with adjustment slots on both legs.
$fn = 48;
width = 50;
depth = 60;
height = 60;
wall = 4;
slot_w = 6.2;
slot_l = 16;

difference() {
    union() {
        cube([width, depth, wall]);
        cube([width, wall, height]);
    }
    for (x = [width / 4, 3 * width / 4 - slot_l])
        hull() {
            translate([x, depth / 2 + wall / 2, -1])
                cylinder(h = wall + 2, d = slot_w);
            translate([x + slot_l, depth / 2 + wall / 2, -1])
                cylinder(h = wall + 2, d = slot_w);
        }
    for (x = [width / 4, 3 * width / 4 - slot_l])
        hull() {
            translate([x, -1, height / 2 + wall / 2]) rotate([-90, 0, 0])
                cylinder(h = wall + 2, d = slot_w);
            translate([x + slot_l, -1, height / 2 + wall / 2]) rotate([-90, 0, 0])
                cylinder(h = wall + 2, d = slot_w);
        }
}

// Vented cover with a row of through slots.
$fn = 48;
width = 120;
depth = 50;
thickness = 4;
slot_w = 4;
slot_n = 5;
margin = 11;
pitch = (width - 2 * margin - slot_w) / (slot_n - 1);

difference() {
    cube([width, depth, thickness]);
    for (i = [0 : slot_n - 1])
        hull() {
            translate([margin + i * pitch + slot_w / 2, margin + slot_w / 2, -1])
                cylinder(h = thickness + 2, d = slot_w);
            translate([margin + i * pitch + slot_w / 2, depth - margin - slot_w / 2, -1])
                cylinder(h = thickness + 2, d = slot_w);
        }
    for (x = [margin / 2, width - margin / 2], y = [margin / 2, depth - margin / 2])
        translate([x, y, -1]) cylinder(h = thickness + 2, d = 3.2);
}

// GT2 pulley, 36 teeth, 6 mm belt.
$fn = 96;
teeth = 36;
belt_w = 6;
bore_d = 6.35;
pitch_d = teeth * 2 / PI;
flange_d = pitch_d + 3;
flange_t = 1.2;
hub_h = 7;
hub_d = bore_d + 7;
eps = 0.01;
// Stack heights cumulatively from one running z. Deriving the hub start as
// 2 * flange_t + belt_w while the flange ended at flange_t + belt_w + flange_t
// left a 1e-15 mm gap for some belt widths, which Manifold exported as a
// degenerate ring of non-manifold edges.
z_belt = flange_t;
z_top_flange = z_belt + belt_w;
z_hub = z_top_flange + flange_t;
total_h = z_hub + hub_h;

difference() {
    union() {
        cylinder(h = flange_t + eps, d = flange_d);
        translate([0, 0, z_belt])
            cylinder(h = belt_w + eps, d = pitch_d);
        translate([0, 0, z_top_flange])
            cylinder(h = flange_t + eps, d = flange_d);
        translate([0, 0, z_hub])
            cylinder(h = hub_h, d = hub_d);
    }
    translate([0, 0, -1]) cylinder(h = total_h + 2, d = bore_d);
    for (i = [0 : teeth - 1])
        rotate([0, 0, i * 360 / teeth])
            translate([pitch_d / 2, 0, z_belt - 0.1])
                cylinder(h = belt_w + 0.2, d = 1.3);
    translate([0, 0, z_hub + hub_h / 2])
        rotate([0, -90, 0]) cylinder(h = hub_d, d = 3.2);
}

// Round pipe flange with a 18 mm neck.
$fn = 96;
bore_d = 42;
outer_d = 70;
bolt_circle = 56;
bolt_n = 6;
bolt_d = 6.5;
flange_t = 6;
neck_l = 18;
neck_d = bore_d + 8;

difference() {
    union() {
        cylinder(h = flange_t, d = outer_d);
        translate([0, 0, flange_t]) cylinder(h = neck_l, d = neck_d);
    }
    translate([0, 0, -1]) cylinder(h = flange_t + neck_l + 2, d = bore_d);
    for (i = [0 : bolt_n - 1])
        rotate([0, 0, i * 360 / bolt_n])
            translate([bolt_circle / 2, 0, -1])
                cylinder(h = flange_t + 2, d = bolt_d);
}

