// Spur gear, module 1, 15 teeth.
$fn = 64;
module_mm = 1;
teeth = 15;
face_w = 6;
bore_d = 5;
pitch_r = module_mm * teeth / 2;
root_r = pitch_r - 1.25 * module_mm;
tooth_t = module_mm * 1.6;

difference() {
    union() {
        cylinder(h = face_w, r = root_r);
        for (i = [0 : teeth - 1])
            rotate([0, 0, i * 360 / teeth])
                hull() {
                    translate([root_r, 0, 0])
                        cylinder(h = face_w, d = tooth_t);
                    translate([pitch_r + module_mm, 0, 0])
                        cylinder(h = face_w, d = tooth_t * 0.55);
                }
    }
    translate([0, 0, -1]) cylinder(h = face_w + 2, d = bore_d);
    translate([bore_d / 2 - 0.4, -1.5, -1])
        cube([1.8, 3.0, face_w + 2]);
}

// Oval two-bolt flange.
$fn = 96;
bore_d = 28;
pad_w = 44;
centres = 66;
bolt_d = 5.5;
flange_t = 6;
neck_l = 12;
neck_d = bore_d + 7;

difference() {
    union() {
        hull()
            for (x = [-centres / 2, centres / 2])
                translate([x, 0, 0]) cylinder(h = flange_t, d = pad_w);
        translate([0, 0, flange_t]) cylinder(h = neck_l, d = neck_d);
    }
    translate([0, 0, -1]) cylinder(h = flange_t + neck_l + 2, d = bore_d);
    for (x = [-centres / 2, centres / 2])
        translate([x, 0, -1]) cylinder(h = flange_t + 2, d = bolt_d);
}

