    for (x = [width / 4, 3 * width / 4 - slot_l])
        hull() {
            translate([x, -1, height / 2 + wall / 2]) rotate([-90, 0, 0])
                cylinder(h = wall + 2, d = slot_w);
            translate([x + slot_l, -1, height / 2 + wall / 2]) rotate([-90, 0, 0])
                cylinder(h = wall + 2, d = slot_w);
