bolt_d = 5.5;
flange_t = 9;
neck_l = 22;
neck_d = bore_d + 8;

difference() {
    union() {
        cylinder(h = flange_t, d = outer_d);
        translate([0, 0, flange_t]) cylinder(h = neck_l, d = neck_d);
    }
    translate([0, 0, -1]) cylinder(h = flange_t + neck_l + 2, d = bore_d);
    for (i = [0 : bolt_n - 1])
        rotate([0, 0, i * 360 / bolt_n])
            translate([bolt_circle / 2, 0, -1])
                cylinder(h = flange_t + 2, d = bolt_d);
}

// NEMA 23 motor mount plate.
$fn = 72;
size = 75.14;
thickness = 7;
spacing = 47.14;
bolt_d = 5.2;
pilot_d = 38.5;
radius = 5;

difference() {
    hull()
        for (x = [radius, size - radius], y = [radius, size - radius])
            translate([x, y, 0]) cylinder(h = thickness, r = radius);
    translate([size / 2, size / 2, -1])
        cylinder(h = thickness + 2, d = pilot_d);
    for (dx = [-spacing / 2, spacing / 2], dy = [-spacing / 2, spacing / 2])
        translate([size / 2 + dx, size / 2 + dy, -1])
            cylinder(h = thickness + 2, d = bolt_d);
}

// Enclosure base with four PCB standoffs.
$fn = 48;
width = 90;
depth = 55;
base_t = 6;
post_h = 7;
post_d = 6;
post_bore = 2.5;
pcb_x = 74;
pcb_y = 35;

union() {
    difference() {
        cube([width, depth, base_t]);
        for (x = [5, width - 5], y = [5, depth - 5])
            translate([x, y, -1]) cylinder(h = base_t + 2, d = 3.2);
    }
    for (dx = [-pcb_x / 2, pcb_x / 2], dy = [-pcb_y / 2, pcb_y / 2])
        translate([width / 2 + dx, depth / 2 + dy, base_t])
            difference() {
                cylinder(h = post_h, d = post_d);
                translate([0, 0, -1])
                    cylinder(h = post_h + 2, d = post_bore);
            }
}

